lid var(--line);background:#fff;padding:8px 10px;border-radius:9px;font-size:11px;font-weight:800;color:#4e5869}.chip.active{border-color:#c9c2ff;background:#f1efff;color:#5145d4}.swatches{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.sw{width:100%;aspect-ratio:1;border-radius:8px;border:2px solid #fff;box-shadow:0 0 0 1px #dfe2e9;cursor:pointer}.custom{display:flex;align-items:center;gap:8px;margin-top:9px}.custom input{width:42px;height:34px;border:0;padding:2px;background:#fff;border-radius:8px}.custom span{font-size:10px;color:var(--muted)}.upload-bg{width:100%;border:1px dashed #cfd4df;background:#fff;border-radius:11px;padding:10px;font-size:11px;font-weight:800;color:#5d6675}.slider{width:100%;accent-color:var(--p)}.slider-line{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-bottom:4px}.main{min-width:0;background:#f1f2f6;display:flex;flex-direction:column}.topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 16px;background:#fff;border-bottom:1px solid var(--line)}.status-pill{display:flex;align-items:center;gap:7px;font-size:11px;font-weight:850}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 4px #dcfce7}.top-actions{display:flex;gap:7px}.mini{border:1px solid var(--line);background:#fff;border-radius:9px;padding:8px 10px;font-size:11px;font-weight:850}.mini.primary{background:var(--p);border-color:var(--p);color:#fff}.canvas-area{position:relative;flex:1;display:grid;place-items:center;padding:30px;min-height:490px;overflow:hidden}.checker{position:absolute;inset:0;background:repeating-conic-gradient(#e2e4e9 0 25%,#f3f4f6 0 50%) 50%/26px 26px;opacity:.75}.canvas-wrap{position:relative;z-index:1;max-width:92%;max-height:450px;box-shadow:0 18px 55px rgba(20,25,45,.16);border-radius:5px;overflow:hidden;background:transparent}.canvas-wrap canvas{display:block;max-width:100%;max-height:450px}.empty{position:relative;z-index:2;width:min(600px,100%);padding:60px 20px;text-align:center;border:2px dashed #cbd0dc;border-radius:22px;background:rgba(255,255,255,.78);backdrop-filter:blur(8px)}.empty .big{font-size:44px}.empty h2{margin:10px 0 5px;font-size:20px}.empty p{font-size:12px;color:var(--muted);margin:0 0 16px}.upload{display:inline-flex;background:var(--p);color:#fff;padding:12px 18px;border-radius:11px;font-weight:900;font-size:12px}.bottom{background:#fff;border-top:1px solid var(--line);padding:12px 16px;display:flex;align-items:center;justify-content:space-between;gap:10px}.progress{flex:1;max-width:520px}.progress-text{font-size:10px;color:var(--muted);margin-bottom:6px}.bar{height:7px;background:#eceef3;border-radius:99px;overflow:hidden}.fill{height:100%;width:0;background:linear-gradient(90deg,var(--p),var(--p2));border-radius:99px;transition:width .25s}.export{background:#111827;color:#fff;border:0;border-radius:11px;padding:12px 18px;font-size:12px;font-weight:900}.input-hidden{display:none}.wait{position:absolute;z-index:5;inset:auto 20px 20px 20px;max-width:460px;margin:auto;background:rgba(17,24,39,.94);color:#fff;border-radius:16px;padding:13px 15px;display:none;box-shadow:0 15px 45px rgba(0,0,0,.22)}.wait strong{font-size:12px}.wait small{display:block;color:#cbd5e1;font-size:10px;margin-top:4px}.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:#a78bfa;margin-right:6px;animation:p 1s infinite}@keyframes p{50%{opacity:.25;transform:scale(.7)}}.results{margin-top:22px;display:none}.result-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.result-head h2{font-size:18px;margin:0}.result-head span{font-size:11px;color:var(--muted)}.result-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:14px;display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.result-card img{max-width:100%;max-height:260px;object-fit:contain;background:repeating-conic-gradient(#e2e2e2 0 25%,#fff 0 50%) 50%/18px 18px;border-radius:10px}.result-actions{display:flex;flex-direction:column;gap:8px}.result-actions a,.result-actions button{border:0;border-radius:10px;padding:11px 14px;background:var(--p);color:#fff;font-size:11px;font-weight:900}.result-actions button{background:#eef0f5;color:#3f4858}.before-after{margin-top:20px}.before-after h3{font-size:15px;margin:0 0 10px}.compare{position:relative;overflow:hidden;border-radius:16px;border:1px solid var(--line);background:#ddd;min-height:180px}.compare img{display:block;width:100%;max-height:430px;object-fit:contain}.compare .after{position:absolute;inset:0;width:50%;overflow:hidden;border-right:2px solid #fff}.compare input{position:absolute;inset:0;width:100%;opacity:0;cursor:ew-resize}.compare-line{position:absolute;top:0;bottom:0;left:50%;width:2px;background:#fff;pointer-events:none}.compare-badge{position:absolute;top:10px;padding:5px 8px;border-radius:7px;background:rgba(17,24,39,.78);color:#fff;font-size:9px;font-weight:900}.compare-badge.l{left:10px}.compare-badge.r{right:10px}@media(max-width:850px){.studio{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line)}.canvas-area{min-height:430px}.result-card{grid-template-columns:1fr}.result-actions{flex-direction:row}.result-actions>*{flex:1}}@media(max-width:560px){.wrap{width:min(100% - 16px,1240px)}.hero{padding-top:25px}.hero h1{letter-spacing:-2px}.studio{border-radius:20px}.side{padding:13px}.tabs{overflow:auto}.tab{min-width:65px}.canvas-area{padding:15px;min-height:370px}.canvas-wrap canvas{max-height:350px}.bottom{align-items:stretch;flex-direction:column}.progress{max-width:none}.swatches{grid-template-columns:repeat(7,1fr)}}
