<main class="wrap">
<section class="hero"><div class="eyebrow">✦ SMARTTOOLZ AI IMAGE STUDIO</div><h1>Remove it. <span>Restyle it.</span> Make it yours.</h1><p>Turn any photo into a polished cutout, product image, profile picture or social creative — right in your browser.</p><div class="trust"><span>🔒 Your image stays on your device</span><span>⚡ AI background removal</span><span>🎨 Instant background studio</span><span>⬇️ HD export</span></div></section>
<section class="studio">
<aside class="side">
<div class="tabs"><button class="tab active" data-tab="remove">Remove</button><button class="tab" data-tab="background">BG</button><button class="tab" data-tab="refine">Refine</button><button class="tab" data-tab="resize">Resize</button><button class="tab" data-tab="export">Export</button></div>
<div class="section panel-remove"><div class="label">AI Background</div><div class="row"><button class="chip active" id="removeBtn">✨ Remove</button><button class="chip" id="restoreBtn">↩ Restore</button></div></div>
<div class="section panel-background"><div class="label">Background</div><div class="row" style="margin-bottom:9px"><button class="chip active" data-bg="transparent">Transparent</button><button class="chip" data-bg="white">White</button><button class="chip" data-bg="black">Black</button></div><div class="swatches" id="swatches"></div><div class="custom"><input id="color" type="color" value="#ffffff"><span>Custom background color</span></div><div style="margin-top:9px"><label class="upload-bg">🖼️ Upload background image<input id="bgPicker" class="input-hidden" type="file" accept="image/*"></label></div></div>
<div class="section panel-refine"><div class="label">Refine & Shadow</div><div class="slider-line"><span>Edge softness</span><b id="softVal">0</b></div><input class="slider" id="soft" type="range" min="0" max="12" value="0"><div class="slider-line" style="margin-top:9px"><span>Shadow</span><b id="shadowVal">0</b></div><input class="slider" id="shadow" type="range" min="0" max="30" value="0"></div>
<div class="section panel-resize"><div class="label">Canvas</div><div class="row"><button class="chip active ratio" data-ratio="1">1:1</button><button class="chip ratio" data-ratio="1.25">4:5</button><button class="chip ratio" data-ratio="1.7778">16:9</button><button class="chip ratio" data-ratio=".5625">9:16</button></div></div>
<div class="section panel-export"><div class="label">Export</div><div class="row"><button class="chip active" data-format="png">PNG</button><button class="chip" data-format="jpeg">JPG</button><button class="chip" data-format="webp">WebP</button></div></div>
<div class="section"><div class="label">Quick actions</div><div class="row"><button class="chip" id="reset">↺ Reset</button><button class="chip" id="newImage">＋ New image</button></div></div>
</aside>
<div class="main">
<div class="topbar"><div class="status-pill"><i class="dot"></i><span id="topStatus">Ready for your image</span></div><div class="top-actions"><button class="mini" id="undo">↶ Undo</button><button class="mini" id="redo">↷ Redo</button></div></div>
<div class="canvas-area"><div class="checker"></div><div class="empty" id="empty"><div class="big">🪄</div><h2>Your AI canvas is waiting</h2><p>Upload a photo and watch SmartToolz detect the subject, remove the background and open the full studio.</p><label class="upload">Choose image<input id="picker" class="input-hidden" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="canvas-wrap" id="canvasWrap" style="display:none"><canvas id="canvas"></canvas></div><div class="wait" id="wait"><strong><span class="pulse"></span><span id="waitTitle">AI is working…</span></strong><small id="waitSub">Preparing your image</small></div></div>
<div class="bottom"><div class="progress"><div class="progress-text" id="progressText">Upload an image to begin</div><div class="bar"><div class="fill" id="fill"></div></div></div><button class="export" id="download">⬇ Export image</button></div>
</div></section>
<section class="results" id="results"><div class="result-head"><h2>Your finished image</h2><span id="resultMeta">Ready to export</span></div><div class="result-card"><img id="resultImg" alt="Processed result"><div class="result-actions"><a id="download2" download="smarttoolz-image.png">⬇ Download</a><button id="editAgain">✦ Keep editing</button></div></div><div class="before-after"><h3>Before / After</h3><div class="compare"><img id="beforeImg" alt="Original"><div class="after"><img id="afterImg" alt="Result"></div><div class="compare-line" id="compareLine"></div><span class="compare-badge l">BEFORE</span><span class="compare-badge r">AFTER</span><input id="compare" type="range" min="0" max="100" value="50"></div></div></section>
</main>
<script type="module">
import { removeBackground } from 'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';
const $=id=>document.getElementById(id);let original=null,cutout=null,bgImage=null,mode='transparent',format='png',ratio=1,soft=0,shadow=0,history=[],future=[];
const picker=$('picker'),bgPicker=$('bgPicker'),canvas=$('canvas'),ctx=canvas.getContext('2d'),empty=$('empty'),canvasWrap=$('canvasWrap');
const colors=['#ffffff','#000000','#f3f4f6','#e5e7eb','#fee2e2','#ffedd5','#fef3c7','#dcfce7','#dbeafe','#e0e7ff','#f3e8ff','#fce7f3','#0f172a','#1e3a8a'];
$('swatches').innerHTML=colors.map(c=>`<button class="sw" style="background:${c}" data-color="${c}" aria-label="${c}"></button>`).join('');
function status(t){$('topStatus').textContent=t;$('progressText').textContent=t}function progress(n){$('fill').style.width=n+'%'}
function wait(on,title='AI is working…',sub='Preparing your image'){ $('wait').style.display=on?'block':'none';$('waitTitle').textContent=title;$('waitSub').textContent=sub }
function imgURL(blob){return URL.createObjectURL(blob)}
function loadImage(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src})}
async function blobFromCanvas(){return new Promise(r=>canvas.toBlob(r,format==='png'?'image/png':format==='webp'?'image/webp':'image/jpeg',.94))}
function draw(){if(!original)return;const base=cutout||original;let w=base.naturalWidth||base.width,h=base.naturalHeight||base.height;if(ratio!==1){const target=w/h; if(target>ratio)h=Math.round(w/ratio);else w=Math.round(h*ratio)}canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);if(mode==='transparent'){ }else if(bgImage){ctx.drawImage(bgImage,0,0,w,h)}else if(mode.startsWith('gradient')){const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,$('color').value);g.addColorStop(1,'#ffffff');ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}else{ctx.fillStyle=mode;ctx.fillRect(0,0,w,h)}const x=(w-(base.naturalWidth||base.width))/2,y=(h-(base.naturalHeight||base.height))/2;if(shadow>0){ctx.save();ctx.shadowColor='rgba(0,0,0,.28)';ctx.shadowBlur=shadow;ctx.shadowOffsetY=Math.round(shadow/3);ctx.drawImage(base,x,y);ctx.restore()}else ctx.drawImage(base,x,y);canvasWrap.style.display='block';empty.style.display='none';}
async function process(file){original=await loadImage(URL.createObjectURL(file));cutout=null;mode='transparent';ratio=1;soft=0;shadow=0;history=[];future=[];draw();wait(true,'Reading your image…','Loading the local AI model');progress(8);status('AI model loading on your device…');try{cutout=await removeBackground(file,{output:{format:'image/png',quality:1},progress:(key,current,total)=>{const pct=total?Math.min(88,10+(current/total)*78):25;progress(pct);if(key==='fetch')status('Downloading AI model locally…');else status('AI is separating the subject…')}});cutout=await loadImage(URL.createObjectURL(cutout));progress(92);wait(true,'Refining the cutout…','Cleaning the subject edges');draw();progress(100);wait(false);status('Done — your subject is ready to style ✨');showResult();}catch(e){wait(false);status('Could not process this image. Try another photo.');console.error(e)}}
async function showResult(){const b=await blobFromCanvas(),u=imgURL(b);$('resultImg').src=u;$('download2').href=u;$('download2').download='smarttoolz-'+(format==='png'?'image.png':format==='jpeg'?'image.jpg':'image.webp');$('beforeImg').src=original.src;$('afterImg').src=u;$('results').style.display='block';$('resultMeta').textContent=`${format.toUpperCase()} • ${canvas.width} × ${canvas.height}px`}
function save(){history.push({mode,color:$('color').value,ratio,soft,shadow});if(history.length>20)history.shift();future=[]}
function apply(){draw();showResult()}
picker.onchange=e=>{if(e.target.files[0])process(e.target.files[0]);e.target.value=''};bgPicker.onchange=async e=>{if(!e.target.files[0])return;bgImage=await loadImage(URL.createObjectURL(e.target.files[0]));mode='image';save();apply();status('Background image applied');};
$('removeBtn').onclick=()=>{if(original){save();cutout=cutout||null;mode='transparent';apply();status('Background removed — transparent canvas ready')}};
$('restoreBtn').onclick=()=>{if(original){save();mode='transparent';cutout=null;apply();status('Original background restored')}};
document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{if(!original)return;save();mode=b.dataset.bg==='transparent'?'transparent':b.dataset.bg;bgImage=null;document.querySelectorAll('[data-bg]').forEach(x=>x.classList.remove('active'));b.classList.add('active');apply()});
document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{if(!original)return;save();mode=b.dataset.color;$('color').value=b.dataset.color;apply()});
$('color').oninput=()=>{if(original){mode=$('color').value;apply()}};
$('soft').oninput=e=>{$('softVal').textContent=e.target.value;soft=+e.target.value;apply()};$('shadow').oninput=e=>{$('shadowVal').textContent=e.target.value;shadow=+e.target.value;apply()};
document.querySelectorAll('.ratio').forEach(b=>b.onclick=()=>{save();ratio=+b.dataset.ratio;document.querySelectorAll('.ratio').forEach(x=>x.classList.remove('active'));b.classList.add('active');apply()});
document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.classList.remove('active'));b.classList.add('active');showResult()});
$('download').onclick=async()=>{if(!original)return;const b=await blobFromCanvas(),u=imgURL(b),a=document.createElement('a');a.href=u;a.download='smarttoolz-'+(format==='png'?'image.png':format==='jpeg'?'image.jpg':'image.webp');a.click();status('Export complete — your image is saved ✓')};$('editAgain').onclick=()=>window.scrollTo({top:document.querySelector('.studio').offsetTop-20,behavior:'smooth'});
$('newImage').onclick=()=>picker.click();$('reset').onclick=()=>{if(!original)return;mode='transparent';bgImage=null;ratio=1;soft=0;shadow=0;$('soft').value=0;$('shadow').value=0;$('softVal').textContent=0;$('shadowVal').textContent=0;draw();status('Canvas reset')};
$('undo').onclick=()=>{const s=history.pop();if(!s)return;future.push({mode,color:$('color').value,ratio,soft,shadow});mode=s.mode;$('color').value=s.color;ratio=s.ratio;soft=s.soft;shadow=s.shadow;draw()};$('redo').onclick=()=>{const s=future.pop();if(!s)return;history.push({mode,color:$('color').value,ratio,soft,shadow});mode=s.mode;$('color').value=s.color;ratio=s.ratio;soft=s.soft;shadow=s.shadow;draw()};
$('compare').oninput=e=>{$('afterImg').parentElement.style.width=e.target.value+'%';$('compareLine').style.left=e.target.value+'%'};
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');const target=t.dataset.tab;document.querySelectorAll('.section').forEach(s=>s.style.display='none');const p=document.querySelector('.panel-'+target);if(p)p.style.display='block';if(target==='remove')document.querySelector('.panel-remove').style.display='block';if(target==='background')document.querySelector('.panel-background').style.display='block';if(target==='refine')document.querySelector('.panel-refine').style.display='block';if(target==='resize')document.querySelector('.panel-resize').style.display='block';if(target==='export')document.querySelector('.panel-export').style.display='block'});
</script></body></html>